Here's a modern data-driven MSTest test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;
using Contoso.Pricing;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    // ─── DataRow: inline values for CalculateTotal ───────────────────────
    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 2, 0.10, 22.00, DisplayName = "Two items, 10% tax")]
    [DataRow(5.50, 3, 0.20, 19.80, DisplayName = "Three items, 20% tax")]
    [DataRow(0.00, 5, 0.15, 0.00, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.05, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ─── DynamicData with ValueTuples: complex discount scenarios ────────
    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10m, 90m),
        (200m, 25m, 150m),
        (50m, 0m, 50m),
        (80m, 100m, 0m),
        (49.99m, 50m, 24.995m),
    ];

    // ─── Exception cases ─────────────────────────────────────────────────
    [TestMethod]
    [DataRow(-1.0, 1, 0.1, DisplayName = "Negative unit price")]
    public void CalculateTotal_InvalidUnitPrice_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DataRow(10.0, -1, 0.1, DisplayName = "Negative quantity")]
    public void CalculateTotal_InvalidQuantity_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate));
    }

    [TestMethod]
    [DynamicData(nameof(InvalidDiscountData))]
    public void ApplyDiscount_InvalidPercent_Throws(decimal price, decimal discountPercent)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(price, discountPercent));
    }

    public static IEnumerable<(decimal price, decimal discountPercent)> InvalidDiscountData =>
    [
        (100m, -1m),
        (100m, 101m),
    ];
}
```

**Key patterns demonstrated:**

| Pattern | Usage |
|---------|-------|
| **`[DataRow]`** | Inline primitive values (note: `decimal` literals aren't compile-time constants, so use `double` and cast) |
| **`DynamicData` + ValueTuples** | Type-safe complex data without `object[]` boxing (MSTest 3.7+) |
| **`Assert.ThrowsExactly<T>`** | Modern exception testing (replaces `[ExpectedException]`) |
| **Sealed class + readonly field** | Best practice for test class design |
| **`DisplayName`** | Readable test names in Test Explorer |

For the `DynamicData` approach, parameter names in the tuple match the test method parameters — MSTest destructures them automatically.
